-- ============================================================
-- マイ個人 — RESTAURAÇÃO CONTA INDIVIDUAL (2026)
-- Sem descontos | Apenas horas e valor/hora dos meses trabalhados (1 a 9)
-- Meses 10, 11 e 12 deixados totalmente em branco para preenchimento manual
-- Intervalo: exatamente 1 hora (01:00:00)
-- Execute este script no SQL Editor do Supabase Dashboard
-- ============================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

DO $$
DECLARE
  v_user_id UUID := '9e3119e8-a0f9-4536-af47-c09d37553c53';
  v_email TEXT := 'ruyhayashihara@gmail.com';
  v_name TEXT := 'Ruy Hayashihara';
  v_password TEXT := 'MudeSuaSenha123!';
  v_existing_id UUID;
BEGIN
  -- 1. Garante a conta individual em auth.users
  SELECT id INTO v_existing_id FROM auth.users WHERE email = v_email;
  IF v_existing_id IS NOT NULL AND v_existing_id != v_user_id THEN
    DELETE FROM public.perfil_usuario WHERE id = v_existing_id;
    DELETE FROM auth.users WHERE id = v_existing_id;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = v_user_id) THEN
    INSERT INTO auth.users (
      instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change
    ) VALUES (
      '00000000-0000-0000-0000-000000000000', v_user_id, 'authenticated', 'authenticated',
      v_email, crypt(v_password, gen_salt('bf')), NOW(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      jsonb_build_object('nome', v_name, 'tipo_perfil', 'individual'),
      '2026-02-22 06:18:57+00'::timestamptz, NOW(), '', '', '', ''
    );
    RAISE NOTICE 'Conta individual criada: %', v_email;
  ELSE
    UPDATE auth.users SET
      encrypted_password = crypt(v_password, gen_salt('bf')),
      email_confirmed_at = NOW(),
      raw_user_meta_data = jsonb_build_object('nome', v_name, 'tipo_perfil', 'individual'),
      updated_at = NOW()
    WHERE id = v_user_id;
    RAISE NOTICE 'Conta individual atualizada: %', v_email;
  END IF;

  -- 2. Configura o perfil com perfil INDIVIDUAL e valor_hora base
  INSERT INTO public.perfil_usuario (
    id, nome, tipo_perfil, moeda, valor_hora_padrao, regime_declaracao, ano_fiscal_atual
  ) VALUES (
    v_user_id, v_name, 'individual', '¥', 2200, '青色 Azul', 2026
  )
  ON CONFLICT (id) DO UPDATE SET
    tipo_perfil = 'individual',
    nome = v_name,
    valor_hora_padrao = 2200,
    ano_fiscal_atual = 2026;

  RAISE NOTICE 'Perfil individual configurado com sucesso.';
END $$;

-- 3. Limpa registros anteriores para inserção limpa
DELETE FROM public.registro_diario WHERE usuario_id = '9e3119e8-a0f9-4536-af47-c09d37553c53' AND EXTRACT(YEAR FROM data) = 2026;
DELETE FROM public.desconto_mensal WHERE usuario_id = '9e3119e8-a0f9-4536-af47-c09d37553c53' AND ano = 2026;
DELETE FROM public.resumo_mensal WHERE usuario_id = '9e3119e8-a0f9-4536-af47-c09d37553c53' AND ano = 2026;

